function itemFeedbackUnread(blockId){const f=itemFeedback(blockId)||{},t=String(f.updatedAt||f.editedAt||'');if(!t||!(f.comment||f.score||(f.status&&f.status!=='none')||f.editedAt||(f.thread||[]).length))return false;let r='';try{r=localStorage.getItem(itemFeedbackReadKey(blockId))||''}catch{}return !r||new Date(t)>new Date(r)}
