function feedbackEntriesForSection(id){const section=(schema?.sections||[]).find(s=>s.id===id),out=[];const sf=sectionFeedback(id);if(sf?.updatedAt&&(sf.comment||sf.status))out.push(sf);for(const b of(section?.blocks||[])){const f=itemFeedback(b.id);if(f?.updatedAt&&(f.comment||f.score||(f.status&&f.status!=='none')||f.editedAt))out.push(f)}return out}
