 const review=studentReviewFor(block.id),resubmitted=itemRevisionResubmitted(block.id),teacherCount=(Array.isArray(f.thread)?f.thread.length:0)||(f.updatedAt?1:0),studentCount=studentEvents.length||(review?.submittedAt?1:0),count=teacherCount+studentCount,hasData=!!(f.comment||f.score||(f.status&&f.status!=='none')||f.editedAt||(f.thread||[]).length||studentEvents.length||review?.submittedAt);
