function progress(){const blocks=publishedSections().flatMap(s=>(s.blocks||[]).filter(b=>b.type!=="theory"&&b.type!=="logic_chain"));let filled=0;for(const b of blocks){const s=publishedSections().find(x=>(x.blocks||[]).some(y=>y.id===b.id));const a=answerFor(s,b)||{};if(b.type==='table'&&Array.isArray(a.rows)&&a.rows.some(r=>r.some(v=>String(v||'').trim())))filled++;else if(b.type==='file'&&Array.isArray(a.files)&&a.files.length)filled++;else if(b.type==='material_collection'&&Array.isArray(a.items)&&a.items.length)filled++;else if(b.type==='checklist'&&Array.isArray(a.values)&&a.values.length)filled++;else if(b.type==='conflict_builder'&&String(a.summary||a.value||a.subject||a.content||'').trim())filled++;else if(String(a.value||'').trim())filled++}return{total:blocks.length,filled,pct:blocks.length?Math.round(filled/blocks.length*100):0}}
