 const appXml=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><Application>REMS Control</Application></Properties>`;
 const z=new JSZip();z.file('[Content_Types].xml',contentTypes);z.folder('_rels').file('.rels',rels);z.folder('word').file('document.xml',documentXml).file('styles.xml',styles).file('header1.xml',header).file('header2.xml',firstHeader);z.folder('word').folder('_rels').file('document.xml.rels',docRels);z.folder('docProps').file('core.xml',core).file('app.xml',appXml);return z.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})
